"""Gzip firmware/web/index.html into firmware/include/web_index.h (served as-is
with Content-Encoding: gzip). Run: pixi run web"""

import gzip
import sys
from pathlib import Path


def main(src: str, dst: str) -> None:
    html = Path(src).read_bytes()
    data = gzip.compress(html, compresslevel=9, mtime=0)  # mtime 0: reproducible output
    rows = [", ".join(f"0x{b:02x}" for b in data[i : i + 16]) for i in range(0, len(data), 16)]
    body = ",\n    ".join(rows)
    Path(dst).write_text(
        "// Generated by `pixi run web` from firmware/web/index.html. Do not edit.\n"
        "#pragma once\n\n#include <stddef.h>\n#include <stdint.h>\n\n"
        f"constexpr size_t kWebIndexGzLen = {len(data)};  // {len(html)} bytes uncompressed\n"
        f"static const uint8_t kWebIndexGz[{len(data)}] = {{\n    {body}\n}};\n",
        encoding="ascii",
    )
    print(f"{dst}: {len(html)} -> {len(data)} bytes")


if __name__ == "__main__":
    main(*sys.argv[1:3])
